python3 - <<'PY'
import json, re, subprocess, os, glob
unk = json.load(open('/tmp/lk_result.json'))['unknown']
# grep each short name in the project sources; classify private vs absent
srcs = {}
for root,_,fs in os.walk('AlgebraicJacobian'):
    for f in fs:
        if f.endswith('.lean'):
            p=os.path.join(root,f); srcs[p]=open(p).read()
priv=[]; pub=[]; absent=[]
for name in unk:
    short = name.split('.')[-1]
    found=None
    for p,t in srcs.items():
        for m in re.finditer(r'^(private )?(?:noncomputable )?(theorem|lemma|def|abbrev|instance|structure)\s+'+re.escape(short)+r'\b', t, re.M):
            found=(p, bool(m.group(1))); break
        if found: break
    if found is None: absent.append(name)
    elif found[1]: priv.append((name,found[0]))
    else: pub.append((name,found[0]))
print(f'unresolvable pins on proof-\\leanok nodes: {len(unk)}')
print(f'  PRIVATE in this project (real declaration, unaddressable): {len(priv)}')
print(f'  public but name mismatch (renamed/moved)                : {len(pub)}')
print(f'  not found in this project at all                        : {len(absent)}')
for n,p in priv[:6]: print('    priv:', n, '->', p)
for n,p in pub[:6]: print('    pub :', n, '->', p)
for n in absent[:10]: print('    absent:', n)
json.dump({'priv':priv,'pub':pub,'absent':absent}, open('/tmp/unres_class.json','w'))
PY

